import hashlib

# Simulasi Rebalancing Vektor Menggunakan Consistent Hash Ring Tanpa Downtime
class ConsistentHashRing:
    def __init__(self, nodes, virtual_replicas=3):
        self.virtual_replicas = virtual_replicas
        self.ring = dict()
        self.sorted_keys = []
        for node in nodes:
            self.add_node(node)

    def _hash(self, key):
        return int(hashlib.md5(key.encode('utf-8')).hexdigest(), 16) % (2**32)

    def add_node(self, node):
        for i in range(self.virtual_replicas):
            vkey = f"{node}#v{i}"
            h = self._hash(vkey)
            self.ring[h] = node
            self.sorted_keys.append(h)
        self.sorted_keys.sort()

    def get_node(self, doc_id):
        if not self.ring:
            return None
        h = self._hash(doc_id)
        # Binary search clockwise
        for key in self.sorted_keys:
            if h <= key:
                return self.ring[key]
        return self.ring[self.sorted_keys[0]]

# Evaluasi rebalancing ketika 1 node baru ditambahkan (dari 3 node menjadi 4 node)
initial_nodes = ["node-1", "node-2", "node-3"]
ring = ConsistentHashRing(initial_nodes, virtual_replicas=10)

n_docs = 1_000
initial_mapping = {f"doc_{i}": ring.get_node(f"doc_{i}") for i in range(n_docs)}

# Tambah Node 4
ring.add_node("node-4")
new_mapping = {f"doc_{i}": ring.get_node(f"doc_{i}") for i in range(n_docs)}

moved_docs = sum(1 for i in range(n_docs) if initial_mapping[f"doc_{i}"] != new_mapping[f"doc_{i}"])
fraction_moved = moved_docs / n_docs

print(f"Evaluasi Consistent Hashing Rebalancing ({n_docs} Dokumen Vektor):")
print(f"  Klaster Awal           : {initial_nodes}")
print(f"  Klaster Baru           : {initial_nodes + ['node-4']}")
print(f"  Dokumen yang Berpindah : {moved_docs}/{n_docs} ({fraction_moved*100:.1f}%)")
print(f"  Perpindahan Ideal (1/4): 25.0% (Efisiensi Rebalancing Terbukti Tinggi!)")

import numpy as np

# Simulasi Pemisahan Komputasi dan Penyimpanan (Disaggregated Architecture)
class SharedObjectStore:
    def __init__(self):
        self.storage = {}

    def put_immutable_segment(self, segment_id, vector_matrix):
        # Menyimpan segmen beku di S3/Object Storage
        self.storage[segment_id] = vector_matrix

    def get_segment(self, segment_id):
        return self.storage[segment_id]

class StatelessQueryNode:
    def __init__(self, node_id, object_store):
        self.node_id = node_id
        self.object_store = object_store
        self.local_cache = {}  # Local memory/NVMe cache

    def load_segment_to_cache(self, segment_id):
        if segment_id not in self.local_cache:
            self.local_cache[segment_id] = self.object_store.get_segment(segment_id)

    def search_local(self, q_vec, segment_ids, top_k=2):
        candidates = []
        for sid in segment_ids:
            self.load_segment_to_cache(sid)
            matrix = self.local_cache[sid]
            scores = np.dot(matrix, q_vec)
            for idx, sc in enumerate(scores):
                candidates.append((f"{sid}_doc{idx}", float(sc)))
        candidates.sort(key=lambda x: x[1], reverse=True)
        return candidates[:top_k]

np.random.seed(42)
dim = 4
s3 = SharedObjectStore()
# Index builder menyimpan 2 segmen terkompresi ke S3
s3.put_immutable_segment("seg_A", np.array([[0.9, 0.1, 0.0, 0.1], [0.1, 0.8, 0.2, 0.0]]))
s3.put_immutable_segment("seg_B", np.array([[0.85, 0.15, 0.05, 0.0], [0.0, 0.1, 0.9, 0.3]]))

# Autoscaler memunculkan 2 Query Node baru secara instan (stateless)
q_node1 = StatelessQueryNode("q_worker_1", s3)
q_vec = np.array([1.0, 0.0, 0.0, 0.0])

res = q_node1.search_local(q_vec, ["seg_A", "seg_B"], top_k=2)
print("Eksekusi Kueri pada Stateless Query Node Cloud-Native:")
for rank, (doc, sc) in enumerate(res, 1):
    print(f"  Hasil {rank}: {doc} (Skor: {sc:.4f}) [Dimuat dari Shared Object Store]")

import numpy as np
import time

# Simulasi Change Data Capture (CDC) & Snapshotting Point-in-Time
class CDCVectorEmitter:
    def __init__(self):
        self.event_stream = []
        self.current_state = {}
        self.version = 0

    def mutate(self, op_type, doc_id, vector=None):
        self.version += 1
        event = {
            "version": self.version,
            "op": op_type,
            "id": doc_id,
            "vector": vector.tolist() if vector is not None else None
        }
        self.event_stream.append(event)
        if op_type in ("INSERT", "UPDATE"):
            self.current_state[doc_id] = vector
        elif op_type == "DELETE" and doc_id in self.current_state:
            del self.current_state[doc_id]
        return event

    def create_snapshot(self):
        # Snapshot status point-in-time yang konsisten
        return {"snapshot_version": self.version, "data": dict(self.current_state)}

# Replikasi Standby Consumer (Menyerap CDC)
class StandbyReplica:
    def __init__(self):
        self.replica_state = {}
        self.last_applied_version = 0

    def apply_events(self, events):
        for ev in events:
            if ev["version"] > self.last_applied_version:
                if ev["op"] in ("INSERT", "UPDATE"):
                    self.replica_state[ev["id"]] = np.array(ev["vector"])
                elif ev["op"] == "DELETE" and ev["id"] in self.replica_state:
                    del self.replica_state[ev["id"]]
                self.last_applied_version = ev["version"]

primary = CDCVectorEmitter()
standby = StandbyReplica()

# Mutasi primer
primary.mutate("INSERT", "user_101", np.array([0.1, 0.9]))
primary.mutate("INSERT", "user_102", np.array([0.4, 0.6]))
snap = primary.create_snapshot()
primary.mutate("DELETE", "user_101")

# Replikasi standby menyerap stream event
standby.apply_events(primary.event_stream)

print("Simulasi CDC & Disaster Recovery Point-in-Time Snapshot:")
print(f"  Versi Primer Terkini   : v{primary.version} ({len(primary.current_state)} item aktif)")
print(f"  Versi Snapshot Backup  : v{snap['snapshot_version']} ({len(snap['data'])} item tersimpan)")
print(f"  Versi Standby Replica  : v{standby.last_applied_version} ({len(standby.replica_state)} item tersinkron)")
print(f"  Lag Replikasi CDC      : {primary.version - standby.last_applied_version} event (RPO tercapai sempurna!)")
